function normalizeKey(key){const k=(key||'').toLowerCase();if(k==='a'||k==='arrowleft')return'left';if(k==='d'||k==='arrowright')return'right';if(k===' '||k==='spacebar'||k==='arrowup'||k==='w')return'jump';if(k==='j'||k==='x')return'attack';if(k==='k'||k==='c')return'howl';if(k==='shift')return'dash';return null}
function setInput(source,key,down){if(!held[key])held[key]=new Set();const wasDown=held[key].size>0;if(down)held[key].add(source);else held[key].delete(source);keys[key]=held[key].size>0;return down&&!wasDown}
function activate(key){if(key==='jump')jump();else if(key==='attack')attack();else if(key==='howl')howl();else if(key==='dash')dash()}
function clearInputs(){for(const key in held){held[key].clear();keys[key]=false}}
addEventListener('keydown',e=>{const key=normalizeKey(e.key);if(key){e.preventDefault();const source='keyboard:'+key;if(setInput(source,key,true))activate(key)}if(e.key==='Enter'&&(mode==='title'||mode==='dead'||mode==='win')){e.preventDefault();start()}});
